CustomField.formula:
IF(
/*If Account is Country Parent, stores Primary_BDE__c value */
ISPICKVAL(IM_Hierarchy_Level__c, 'Country Parent'), Primary_BDE__c ,
IF(
/*If Account is Sales site, stores Country Parent Account's Primary_BDE__c by traversing one level up the hierarchy*/
AND(ISPICKVAL(IM_Hierarchy_Level__c, 'Sales (Site)'),NOT(ISBLANK(ParentId))), Parent.Primary_BDE__c,
IF(
/*If Account is Parent HQ, stores Country Parent Account's Primary_BDE__c by traversing one level up the hierarchy*/
ISPICKVAL(IM_Hierarchy_Level__c, 'Parent HQ'), Parent.Primary_BDE__c,Primary_BDE__c)))
